r"""Where Boardwright keeps its files.

Everything per user lives under one folder, ``%USERPROFILE%\Boardwright``
(override with ``BOARDWRIGHT_HOME``):

    workspace\        engine <-> Altium request/response files
    altium-scripts\   the Altium script project (StartMCPServer)
    verified\         parts that passed a full run (index.md, libraries, cards)
    fab_profiles\     fab-house capability profiles (JSON, with sources)
    runs\             one folder per design run (reports)

The install folder (runtime, skills, docs) is separate and read-only in use.
"""
from __future__ import annotations

import os
import sys
from pathlib import Path
from typing import Optional

HOME_ENV = "BOARDWRIGHT_HOME"


def _profile() -> Path:
    userprofile = os.environ.get("USERPROFILE")
    return Path(userprofile) if userprofile else Path.home()


def home() -> Path:
    override = os.environ.get(HOME_ENV)
    return Path(override) if override else _profile() / "Boardwright"


def workspace() -> Path:
    return home() / "workspace"


def altium_scripts() -> Path:
    return home() / "altium-scripts"


def script_project() -> Path:
    return altium_scripts() / "Altium_API.PrjScr"


def verified() -> Path:
    return home() / "verified"


def fab_profiles() -> Path:
    return home() / "fab_profiles"


def runs() -> Path:
    return home() / "runs"


def data_dirs() -> dict[str, Path]:
    return {
        "workspace": workspace(),
        "altium_scripts": altium_scripts(),
        "verified": verified(),
        "fab_profiles": fab_profiles(),
        "runs": runs(),
    }


def legacy_home() -> Path:
    """The folder used before Boardwright (plain eda-agent installs)."""
    return _profile() / "EDA Agent"


def install_root() -> Optional[Path]:
    """The Boardwright install folder when running from its bundled runtime
    (``<root>\\runtime\\python.exe``); None in a development environment."""
    exe = Path(sys.executable).resolve()
    if exe.parent.name.lower() == "runtime" and (exe.parent.parent / "skills").is_dir():
        return exe.parent.parent
    return None
